// MIT. Managed launch identity for the original private NocoDB source workspace.
import { DatabaseSync } from 'node:sqlite';
import { constants } from 'node:fs';
import { open, lstat, realpath } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomUUID } from 'node:crypto';
import { absolute, privateDirectory, readPrivate, object, digest, identity, fault } from '../../postgres/publisher/files.mjs';
import { normalizeConnections } from './provider.mjs';

export const NOCODB_STARTUP_SCHEMA = 'stellar-forge.nocodb-authoring-startup.v1';
const WORKSPACE = 'stellar-forge.nocodb-authoring.v1';
const HASH = /^[a-f0-9]{64}$/;
const SOURCE_FILES = ['launch.mjs', 'model.mjs', 'cli.mjs', 'server.mjs', 'provider.mjs', 'packet.mjs', 'browser.mjs', 'index.html', 'style.css'];
const SOURCE_DIRECTORY = dirname(fileURLToPath(import.meta.url));
const changed = () => fault('NOCODB_MANAGED_INPUT_CHANGED',
  'Review the current source workspace, connection file and installed runtime before starting.', 409);

function expected(value) {
  if (value !== undefined && !HASH.test(value)) throw fault('NOCODB_MANAGED_HASH_REQUIRED');
}
function inode(stat) {
  return { dev: String(stat.dev), ino: String(stat.ino) };
}
function sameInode(left, right) {
  return left.dev === right.dev && left.ino === right.ino;
}
async function privateDatabase(path) {
  const stat = await lstat(path, { bigint: true });
  if (!stat.isFile() || stat.isSymbolicLink() || stat.nlink !== 1n || stat.mode & 0o077n ||
      await realpath(path) !== path) throw fault('PRIVATE_DATABASE_REQUIRED');
  return stat;
}

/** Fixed read-only query over immutable original settings. Mutable SQLite bytes,
 * revisions, captures and publication records are deliberately not launch input. */
export async function inspectNocoDBAuthoring(directory, { expectedIdentity } = {}) {
  absolute(directory); expected(expectedIdentity);
  await privateDirectory(directory);
  const directoryBefore = await lstat(directory, { bigint: true });
  const database = join(directory, 'sources.sqlite'), before = await privateDatabase(database);
  let db, row;
  try {
    db = new DatabaseSync(database, { readOnly: true });
    db.exec('PRAGMA query_only=ON; BEGIN');
    row = db.prepare('SELECT substr(data,1,65537) AS data,length(CAST(data AS BLOB)) AS bytes FROM settings WHERE id=1').get();
    db.exec('COMMIT');
  } catch (issue) {
    if (issue.errcode === 5 || issue.errcode === 6)
      throw fault('NOCODB_WORKSPACE_READING_BUSY', 'Let the current original workspace action finish, then retry this review.', 409);
    throw fault('NOCODB_ORIGINAL_SETTINGS_UNREADABLE',
      'Open the original workspace with the NocoDB status command to reconcile its SQLite state, then review again.', 409);
  } finally { db?.close(); }
  const after = await privateDatabase(database), directoryAfter = await lstat(directory, { bigint: true });
  if (!sameInode(before, after) || !sameInode(directoryBefore, directoryAfter)) throw changed();
  if (!row || typeof row.data !== 'string' || row.bytes > 65536 || Buffer.byteLength(row.data) !== row.bytes)
    throw fault('NOCODB_AUTHORING_BINDING_CHANGED');
  let settings;
  try { settings = JSON.parse(row.data); } catch { throw fault('NOCODB_AUTHORING_BINDING_CHANGED'); }
  if (!object(settings) || settings.schema !== WORKSPACE || typeof settings.createdAt !== 'string' ||
      settings.sourceFile !== join(directory, 'current-source.json') ||
      settings.publisherDirectory !== join(directory, 'publisher'))
    throw fault('NOCODB_AUTHORING_BINDING_CHANGED');
  absolute(settings.targetDirectory);
  const value = {
    schema: 'stellar-forge.nocodb-authoring-identity.v1', directory,
    directoryIdentity: inode(directoryAfter), database: { path: database, ...inode(after) },
    settingsSha256: digest(row.data), settings: {
      schema: settings.schema, createdAt: settings.createdAt, sourceFile: settings.sourceFile,
      publisherDirectory: settings.publisherDirectory, targetDirectory: settings.targetDirectory,
    },
  };
  const sha256 = identity(value);
  if (expectedIdentity !== undefined && sha256 !== expectedIdentity) throw changed();
  return { ...value, sha256 };
}

/** Credential references stay in the original private host file. This performs
 * local validation only and never reads or refreshes a NocoDB token. */
export async function readNocoDBLaunchConnections(file, { expectedSha256 } = {}) {
  expected(expectedSha256);
  if (file === undefined || file === null) {
    if (expectedSha256 !== undefined) throw fault('NOCODB_MANAGED_CONNECTION_REQUIRED');
    return { file: null, sha256: null, connections: {} };
  }
  absolute(file, 'connection file');
  if (await realpath(file) !== file) throw fault('NOCODB_MANAGED_CONNECTION_PATH_REQUIRED');
  const bytes = await readPrivate(file);
  const sha256 = digest(bytes);
  if (expectedSha256 !== undefined && sha256 !== expectedSha256) throw changed();
  let parsed;
  try { parsed = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(bytes)); }
  catch { throw fault('PRIVATE_JSON_INVALID'); }
  return { file, sha256, connections: normalizeConnections(parsed) };
}

async function sourceFile(path) {
  const handle = await open(path, constants.O_RDONLY | constants.O_NOFOLLOW);
  try {
    const before = await handle.stat();
    if (!before.isFile() || before.size > 2 * 1024 * 1024) throw fault('NOCODB_MANAGED_SOURCE_INVALID');
    const bytes = await handle.readFile(), after = await handle.stat();
    if (bytes.length !== before.size || after.size !== before.size ||
        after.mtimeMs !== before.mtimeMs || after.ctimeMs !== before.ctimeMs)
      throw changed();
    return { bytes: bytes.length, sha256: digest(bytes) };
  } finally { await handle.close(); }
}

/** Paths differ after original managed adoption; source bytes must not. */
export async function inspectNocoDBLaunchSource(directory, { expectedSha256 } = {}) {
  absolute(directory, 'source directory'); expected(expectedSha256);
  if (await realpath(directory) !== directory || !(await lstat(directory)).isDirectory())
    throw fault('NOCODB_MANAGED_SOURCE_INVALID');
  const files = [];
  for (const name of SOURCE_FILES) files.push({ name, ...await sourceFile(join(directory, name)) });
  const body = { schema: 'stellar-forge.nocodb-authoring-launch-source.v1', files };
  const sha256 = identity(body);
  if (expectedSha256 !== undefined && sha256 !== expectedSha256) throw changed();
  return { ...body, directory, sha256 };
}

export async function prepareNocoDBManagedLaunch({
  directory, sourceDirectory, expectedSourceSha256, expectedWorkspaceIdentity,
  connectionsFile, expectedConnectionsSha256,
} = {}) {
  absolute(directory); absolute(sourceDirectory);
  if (!HASH.test(expectedSourceSha256 ?? '') || !HASH.test(expectedWorkspaceIdentity ?? '') ||
      Boolean(connectionsFile) !== Boolean(expectedConnectionsSha256))
    throw fault('NOCODB_MANAGED_REVIEW_REQUIRED', 'Use the complete saved Applications launch review.');
  const source = await inspectNocoDBLaunchSource(sourceDirectory, { expectedSha256: expectedSourceSha256 });
  const executed = await inspectNocoDBLaunchSource(SOURCE_DIRECTORY, { expectedSha256: expectedSourceSha256 });
  const connection = await readNocoDBLaunchConnections(connectionsFile, { expectedSha256: expectedConnectionsSha256 });
  return { directory, expectedWorkspaceIdentity, source, executed, connection };
}

export async function nocodbManagedStartup({ launch, workspace, service } = {}) {
  if (!launch || !workspace || !service || launch.directory !== workspace.directory)
    throw fault('NOCODB_MANAGED_REVIEW_REQUIRED');
  const current = await inspectNocoDBAuthoring(workspace.directory, {
    expectedIdentity: launch.expectedWorkspaceIdentity,
  });
  await inspectNocoDBLaunchSource(launch.source.directory, { expectedSha256: launch.source.sha256 });
  await inspectNocoDBLaunchSource(launch.executed.directory, { expectedSha256: launch.source.sha256 });
  return {
    schema: NOCODB_STARTUP_SCHEMA, status: 'NOCODB_AUTHORING_READY',
    instanceId: randomUUID(), pid: process.pid, directory: workspace.directory,
    workspaceIdentity: current.sha256, settingsSha256: current.settingsSha256,
    sourceDirectory: launch.source.directory, launchSourceDirectory: launch.executed.directory,
    sourceSha256: launch.source.sha256, sourceFiles: launch.source.files,
    connectionsFile: launch.connection.file, connectionsSha256: launch.connection.sha256,
    sourceFile: current.settings.sourceFile, publisherDirectory: current.settings.publisherDirectory,
    targetDirectory: current.settings.targetDirectory, nocodbWorkspace: service.url,
  };
}

// MIT. Source authoring over the original NocoDB capture and publication engines.
import { DatabaseSync } from 'node:sqlite';
import { randomUUID } from 'node:crypto';
import { join, dirname } from 'node:path';
import { lstat, chmod, rename, readdir } from 'node:fs/promises';
import { object, bytes, digest, identity, fault, stamp, absolute, privateDirectory, readPrivate,
  readJson, createFile, atomicJson, syncDirectory, acquireWorkspace } from '../../postgres/publisher/files.mjs';
import { MAX_CAPTURE_BYTES, only, compileQueries, sourceSelection, SCALAR_TYPES } from '../declaration.mjs';
import { readNocoDBCapture, bindNocoDBCapture, captureNocoDBSource } from '../capture.mjs';
import { discoverNocoDBTable } from '../http.mjs';
import { NocoDBNumber } from '../values.mjs';
import { openNocoDBSourceFile, inspectNocoDBSource } from '../source.mjs';
import { openNocoDBPublisher } from '../publisher/model.mjs';
import { startPostgresPublisherServer } from '../../postgres/publisher/server.mjs';
import { reviewNocoDBDeployment, prepareNocoDBDeployment, inspectNocoDBDeployment, stageNocoDBDeployment, readNocoDBDeploymentFile } from '../deployment.mjs';
import { inspectNocoDBAuthoring } from './launch.mjs';
import { normalizeConnections, selectConnection, connectionViews, discoveryConfig } from './provider.mjs';
import { MAX_PACKET_BYTES, makeNocoDBSourcePacket, validatePacket, retainPacket, packetFromCapture, createOrVerify } from './packet.mjs';

const SCHEMA = 'stellar-forge.nocodb-authoring.v1';
const UUID = /^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/;
const decode = value => { try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(value)); }
  catch { throw fault('NOCODB_RESOURCE_JSON_INVALID'); } };
const absent = async path => { try { await lstat(path); return false; } catch (issue) { if (issue.code === 'ENOENT') return true; throw issue; } };
const id = value => { if (typeof value !== 'string' || !UUID.test(value)) throw fault('REQUEST_ID_REQUIRED', 'Use one UUID for this operation and its recovery.'); return value; };
const text = (value, label, maximum = 128) => {
  if (typeof value !== 'string' || !value.trim() || value.length > maximum || /[\u0000-\u0008\u000b\u000c\u000e-\u001f]/.test(value))
    throw fault('NOCODB_TEXT_REQUIRED', 'Enter a valid ' + label + '.');
  return value.trim();
};
const integer = (value, label) => { if (!Number.isSafeInteger(value) || value < 0) throw fault('NOCODB_REVISION_REQUIRED', label); return value; };
const privateFault = issue => ({ code: typeof issue.code === 'string' && /^[A-Z0-9_]{1,80}$/.test(issue.code) ? issue.code : 'NOCODB_AUTHORING_FAILED',
  message: issue.code && typeof issue.message === 'string' ? issue.message : 'Inspect the retained operation and selected input.',
  status: [400,403,404,409,413,422,502].includes(issue.status) ? issue.status : 422,
  ...(issue.providerStatus ? { providerStatus: issue.providerStatus } : {}),
  ...(issue.retryAfter ? { retryAfter: issue.retryAfter } : {}),
  ...(issue.requestId ? { providerRequestId: issue.requestId } : {}) });

function sourceConfig(capture, draft) {
  const { fields, ...selected } = capture.manifest.selection;
  const config = { schema: 'stellar-forge.nocodb-source.v1', ...selected,
    connection: { kind: 'capture', file: capture.manifestFile, sha256: capture.manifestSha256 },
    queries: structuredClone(draft.queries) };
  compileQueries(config.queries); bindNocoDBCapture(capture, config);
  return config;
}
function suggestedColumn(field) {
  if (field.id === '$recordId') return { source: '$recordId', type: 'string', encoding: 'identity-text', nullable: false, empty: 'preserve' };
  const numeric = ['Number','Decimal','Currency','Percent','Duration','Rating','Year','AutoNumber'].includes(field.type);
  return { source: field.id, providerType: field.type, type: field.type === 'Checkbox' ? 'boolean' : 'string',
    encoding: numeric ? 'number-text' : 'native', nullable: true, empty: 'preserve' };
}
function displayNative(value) {
  if (value instanceof NocoDBNumber) return { kind: 'number-token', value: value.text };
  if (value === undefined) return { kind: 'missing', value: null };
  if (value === null) return { kind: 'null', value: null };
  if (typeof value === 'string') return { kind: 'string', value: value.slice(0, 240), truncated: value.length > 240 };
  if (typeof value === 'boolean') return { kind: 'boolean', value };
  return { kind: 'structured', value: '[structured provider value]' };
}
export async function openNocoDBAuthoring({ directory, create = false, connections = {}, environment = process.env,
  targetDirectory, seller = null, resource = null, expectedIdentity } = {}) {
  absolute(directory); connections = normalizeConnections(connections);
  const directoryExisted = !await absent(directory);
  if (create && directoryExisted && await absent(join(directory, 'INIT.json')))
    throw fault('NOCODB_AUTHORING_EXISTS', 'Reopen the existing source workspace; this directory has no matching initialization receipt.');
  await privateDirectory(directory, create);
  const release = await acquireWorkspace(directory);
  let db, publisherService = null, deploymentService = null, pending = null, closed = false, closing;
  const deploymentDirectory = join(directory, 'deployments'), releaseDirectory = join(deploymentDirectory, 'releases');
  const lifetime = new AbortController();
  let publisherAccess = Promise.resolve();
  try {
    if (expectedIdentity !== undefined) {
      if (create) throw fault('NOCODB_MANAGED_EXISTING_WORKSPACE_REQUIRED');
      await inspectNocoDBAuthoring(directory, { expectedIdentity });
    }
    let initialization = null;
    if (create) {
      targetDirectory ??= join(directory, 'dataset'); absolute(targetDirectory, 'dataset directory');
      if (targetDirectory !== join(directory, 'dataset') && (targetDirectory === directory ||
          targetDirectory.startsWith(directory + '/') || directory.startsWith(targetDirectory + '/')))
        throw fault('NOCODB_TARGET_DIRECTORY_INVALID');
      const file = join(directory, 'INIT.json'), intent = { schema: SCHEMA, directory, targetDirectory };
      if (await absent(file)) await createOrVerify(file, bytes({ ...intent, createdAt: stamp() }));
      initialization = await readJson(file);
      if (initialization.schema !== intent.schema || initialization.directory !== directory ||
          initialization.targetDirectory !== targetDirectory || typeof initialization.createdAt !== 'string')
        throw fault('NOCODB_INITIALIZATION_CHANGED', 'Resume initialization with its original directory and dataset binding.', 409);
    }
    const database = join(directory, 'sources.sqlite');
    if (!create && await absent(database)) throw fault('NOCODB_AUTHORING_MISSING');
    if (!await absent(database)) {
      const stat = await lstat(database);
      if (!stat.isFile() || stat.isSymbolicLink() || stat.mode & 0o077 || stat.nlink !== 1) throw fault('PRIVATE_DATABASE_REQUIRED');
    }
    db = new DatabaseSync(database); await chmod(database, 0o600);
    db.exec(`PRAGMA foreign_keys=ON; PRAGMA journal_mode=DELETE; PRAGMA synchronous=FULL;
      CREATE TABLE IF NOT EXISTS settings(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS state(id INTEGER PRIMARY KEY CHECK(id=1),data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS captures(id TEXT PRIMARY KEY,data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS discoveries(id TEXT PRIMARY KEY,data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS previews(id TEXT PRIMARY KEY,data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS versions(id INTEGER PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,data TEXT NOT NULL);
      CREATE TABLE IF NOT EXISTS operations(id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload_hash TEXT NOT NULL,
        input TEXT NOT NULL,status TEXT NOT NULL,created TEXT NOT NULL,updated TEXT NOT NULL,result TEXT,error TEXT);
      CREATE TABLE IF NOT EXISTS events(id INTEGER PRIMARY KEY,created TEXT NOT NULL,kind TEXT NOT NULL,operation TEXT,data TEXT NOT NULL);`);
    const transaction = fn => { db.exec('BEGIN IMMEDIATE'); try { const value = fn(); db.exec('COMMIT'); return value; }
      catch (issue) { try { db.exec('ROLLBACK'); } catch {} throw issue; } };
    if (create && !db.prepare('SELECT id FROM settings WHERE id=1').get()) {
      transaction(() => {
        db.prepare('INSERT INTO settings VALUES(1,?)').run(JSON.stringify({ schema: SCHEMA, createdAt: initialization.createdAt,
          targetDirectory, publisherDirectory: join(directory, 'publisher'), sourceFile: join(directory, 'current-source.json') }));
        db.prepare('INSERT INTO state VALUES(1,?)').run(JSON.stringify({ draft: null, draftRevision: 0, selectedVersion: null, selectionRevision: 0 }));
      });
      for (const name of ['inputs', 'captures', 'previews', 'versions', 'interrupted']) await privateDirectory(join(directory, name), true);
      await syncDirectory(directory);
    }
    const settings = JSON.parse(db.prepare('SELECT data FROM settings WHERE id=1').get()?.data ?? 'null');
    if (settings?.schema !== SCHEMA || settings.sourceFile !== join(directory, 'current-source.json') ||
        settings.publisherDirectory !== join(directory, 'publisher') || targetDirectory && targetDirectory !== settings.targetDirectory)
      throw fault('NOCODB_AUTHORING_BINDING_CHANGED');
    for (const name of ['inputs', 'captures', 'previews', 'versions', 'interrupted']) await privateDirectory(join(directory, name), true);
    const current = () => JSON.parse(db.prepare('SELECT data FROM state WHERE id=1').get().data);
    const setState = value => db.prepare('UPDATE state SET data=? WHERE id=1').run(JSON.stringify(value));
    const event = (kind, request, data = {}) => db.prepare('INSERT INTO events(created,kind,operation,data) VALUES(?,?,?,?)')
      .run(stamp(), kind, request, JSON.stringify(data));
    const operation = request => {
      const row = db.prepare('SELECT * FROM operations WHERE id=?').get(id(request));
      if (!row) return null;
      return { id: row.id, kind: row.kind, status: row.status, createdAt: row.created, updatedAt: row.updated,
        result: row.result ? JSON.parse(row.result) : null, error: row.error ? JSON.parse(row.error) : null };
    };
    const captureRecord = request => {
      const row = db.prepare('SELECT data FROM captures WHERE id=?').get(id(request));
      if (!row) throw fault('NOCODB_CAPTURE_NOT_FOUND', 'Choose a retained observation.', 404);
      return JSON.parse(row.data);
    };
