      const row = captureRecord(request);
      const result = await readNocoDBCapture(join(directory, 'captures', row.id, 'capture.json'), row.manifestSha256);
      if (result.manifest.selectionSha256 !== row.selectionSha256 || result.manifest.rowCount !== row.rowCount)
        throw fault('NOCODB_CAPTURE_RESOURCE_CHANGED');
