const overlaps = (a, b) => inside(a, b) || inside(b, a);
function path(value) {
  need(typeof value === 'string' && isAbsolute(value) && resolve(value) === value &&
    value !== '/' && !/[\\\x00-\x1f\x7f]/.test(value),
  'Each OAuth host directory must be an absolute normalized private path.');
  return value;
